import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
const payload = ``;
const files = JSON.parse(zlib.gunzipSync(Buffer.from(payload,"base64")).toString("utf8"));
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)));
for (const [rel, entry] of Object.entries(files)) { const out = path.join(root, rel); if (!out.startsWith(root + path.sep) && out !== root) throw new Error(`Unsafe path: ${rel}`); fs.mkdirSync(path.dirname(out),{recursive:true}); if(entry.type === "base64") fs.writeFileSync(out,Buffer.from(entry.data,"base64")); else fs.writeFileSync(out,entry.data); }
const {execFileSync}=await import("node:child_process");
execFileSync(process.platform === "win32" ? "npx.cmd" : "npx", ["next","build"], {stdio:"inherit"});